<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class QualityRiskSurveyController extends Controller{
private function ok(Request $r){abort_unless($r->user()->isSuperAdmin()||$r->user()->hasRole('admin')||$r->user()->hasRole('quality_head')||$r->user()->canDo('quality.manage'),403);}
public function risks(Request $r){$this->ok($r);$p=$r->attributes->get('academic_period');$rows=DB::table('quality_risks as q')->leftJoin('users as u','u.id','=','q.owner_user_id')->where('q.academic_period_id',$p->id)->select('q.*','u.name as owner_name')->orderByRaw('(probability*impact) DESC')->get();$users=DB::table('users')->orderBy('name')->get();return view('quality.risks',compact('rows','users'));}
public function riskStore(Request $r){$this->ok($r);$p=$r->attributes->get('academic_period');$d=$r->validate(['area'=>'required|string|max:255','title'=>'required|string|max:500','probability'=>'required|integer|min:1|max:5','impact'=>'required|integer|min:1|max:5','mitigation'=>'nullable|string|max:10000','owner_user_id'=>'nullable|exists:users,id']);DB::table('quality_risks')->insert($d+['academic_period_id'=>$p->id,'status'=>'open','created_at'=>now(),'updated_at'=>now()]);return back();}
public function riskUpdate(Request $r,$risk){$this->ok($r);abort_unless(DB::table('quality_risks')->where('id',$risk)->exists(),404);$d=$r->validate(['area'=>'required|string|max:255','title'=>'required|string|max:500','probability'=>'required|integer|min:1|max:5','impact'=>'required|integer|min:1|max:5','mitigation'=>'nullable|string|max:10000','owner_user_id'=>'nullable|exists:users,id']);DB::table('quality_risks')->where('id',$risk)->update($d+['updated_at'=>now()]);return back()->with('success','Риск обновлён');}
public function riskStatus(Request $r,$risk){$this->ok($r);$d=$r->validate(['status'=>'required|in:open,monitoring,mitigated,closed']);abort_unless(DB::table('quality_risks')->where('id',$risk)->exists(),404);DB::table('quality_risks')->where('id',$risk)->update(['status'=>$d['status'],'updated_at'=>now()]);return back()->with('success','Статус риска обновлён');}
public function surveys(Request $r){$this->ok($r);$p=$r->attributes->get('academic_period');$rows=DB::table('quality_surveys')->where('academic_period_id',$p->id)->orderByDesc('id')->get();return view('quality.surveys',compact('rows'));}
public function surveyStore(Request $r){$this->ok($r);$p=$r->attributes->get('academic_period');$d=$r->validate(['audience'=>'required|in:students,teachers,parents,employers','title'=>'required|string|max:500','description'=>'nullable|string|max:5000','starts_on'=>'required|date','ends_on'=>'required|date|after_or_equal:starts_on']);DB::table('quality_surveys')->insert($d+['academic_period_id'=>$p->id,'status'=>'draft','anonymous'=>1,'created_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);return back();}
public function surveyUpdate(Request $r,$survey){$this->ok($r);abort_unless(DB::table('quality_surveys')->where('id',$survey)->exists(),404);$d=$r->validate(['audience'=>'required|in:students,teachers,parents,employers','title'=>'required|string|max:500','description'=>'nullable|string|max:5000','starts_on'=>'required|date','ends_on'=>'required|date|after_or_equal:starts_on']);DB::table('quality_surveys')->where('id',$survey)->update($d+['updated_at'=>now()]);return back()->with('success','Опрос обновлён');}
public function surveyStatus(Request $r,$survey){$this->ok($r);$d=$r->validate(['status'=>'required|in:draft,active,closed,archived']);abort_unless(DB::table('quality_surveys')->where('id',$survey)->exists(),404);if($d['status']==='active')abort_if(DB::table('quality_survey_questions')->where('quality_survey_id',$survey)->count()===0,422,'Добавьте хотя бы один вопрос перед запуском опроса.');DB::table('quality_surveys')->where('id',$survey)->update(['status'=>$d['status'],'updated_at'=>now()]);return back()->with('success','Статус опроса обновлён');}
public function question(Request $r,$survey){$this->ok($r);$d=$r->validate(['question'=>'required|string|max:2000','type'=>'required|in:scale,yes_no,text']);$n=(DB::table('quality_survey_questions')->where('quality_survey_id',$survey)->max('sort_order')??0)+1;DB::table('quality_survey_questions')->insert($d+['quality_survey_id'=>$survey,'sort_order'=>$n,'created_at'=>now(),'updated_at'=>now()]);return back();}
public function report(Request $r){$this->ok($r);$p=$r->attributes->get('academic_period');$groups=DB::table('study_groups')->where('active',1)->orderBy('name')->get();foreach($groups as $g){$grades=DB::table('grade_records as gr')->join('lesson_occurrences as l','l.id','=','gr.lesson_occurrence_id')->where(['l.academic_period_id'=>$p->id,'l.study_group_id'=>$g->id])->whereIn('gr.value',['2','3','4','5']);$g->avg=round((float)$grades->avg(DB::raw('CAST(gr.value AS REAL)')),2);$a=DB::table('attendance_records as a')->join('lesson_occurrences as l','l.id','=','a.lesson_occurrence_id')->where(['l.academic_period_id'=>$p->id,'l.study_group_id'=>$g->id]);$n=(clone $a)->count();$g->attendance=$n?round((clone $a)->whereIn('a.status',['present','late'])->count()*100/$n,1):0;$g->debts=DB::table('semester_results as sr')->join('student_group_memberships as gm','gm.student_id','=','sr.student_id')->where(['sr.academic_period_id'=>$p->id,'gm.academic_period_id'=>$p->id,'gm.study_group_id'=>$g->id])->whereIn(DB::raw('LOWER(sr.value)'),['2','незачет','незачёт','не зачтено'])->count();}return view('quality.report',compact('p','groups'));}
}